commands.command:
error_page 502 503 504 /mantenimiento.html;
location = /mantenimiento.html {
    root /var/www/errores;
    internal;
}

location ~ /\.(?!well-known) {
    deny all;
}

location = /nginx_status {
    stub_status;
    allow 127.0.0.1;
    deny all;
}
